import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"5.6 中间继电器与时间继电器","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-6-zhong-jian-ji-dian-qi-yu-shi-jian-ji-dian-qi.md","filePath":"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-6-zhong-jian-ji-dian-qi-yu-shi-jian-ji-dian-qi.md","lastUpdated":1793095197000}'),r={name:"electrician/low-voltage-electrician/05-chapter-5-chang-yong-di-ya-dian-qi/5-6-zhong-jian-ji-dian-qi-yu-shi-jian-ji-dian-qi.md"};function n(e,t,s,u,h,d){return i(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="_5-6-中间继电器与时间继电器" tabindex="-1">5.6 中间继电器与时间继电器 <a class="header-anchor" href="#_5-6-中间继电器与时间继电器" aria-label="Permalink to &quot;5.6 中间继电器与时间继电器&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>接触器管大电流,而<strong>中间继电器</strong>和<strong>时间继电器</strong>是控制回路里的&quot;小助手&quot;:一个负责&quot;扩路&quot;(增加触点)、一个负责&quot;延时&quot;(到点再动作)。这一节讲清它们的用途,尤其时间继电器是星三角启动、顺序控制的关键元件。</p><h2 id="一、中间继电器-触点不够时的-扩路器" tabindex="-1">一、中间继电器:触点不够时的&quot;扩路器&quot; <a class="header-anchor" href="#一、中间继电器-触点不够时的-扩路器" aria-label="Permalink to &quot;一、中间继电器:触点不够时的&quot;扩路器&quot;&quot;">​</a></h2><p><strong>中间继电器</strong>的作用,是<strong>增加触点的数量和容量</strong>:</p><ul><li>当一个触点(或接触器的辅助触点)不够用时,用中间继电器&quot;中转&quot;一下;</li><li>它的结构和工作原理与接触器相似(电磁式),但<strong>触头容量小</strong>,只用于控制回路,不直接通断主电路;</li><li>主要用途: <ol><li><strong>增加触点数量</strong>:一个信号控制多路输出;</li><li><strong>扩大控制容量</strong>:用小信号控制多个回路;</li><li><strong>实现逻辑转换</strong>:常开常闭组合。</li></ol></li></ul><blockquote><p>💡 <strong>通俗理解</strong>:中间继电器是&quot;信号放大器/中转站&quot;——把&quot;1 个信号&quot;变成&quot;多个同样的信号&quot;。</p></blockquote><p><strong>主要参数</strong>:线圈电压、触头数量、触头额定电流(一般 ≤ 10 A 左右,容量小)。</p><h2 id="二、时间继电器-到点才动作的-定时器" tabindex="-1">二、时间继电器:到点才动作的&quot;定时器&quot; <a class="header-anchor" href="#二、时间继电器-到点才动作的-定时器" aria-label="Permalink to &quot;二、时间继电器:到点才动作的&quot;定时器&quot;&quot;">​</a></h2><p><strong>时间继电器</strong>,在<strong>接收到信号后,经过设定的延时时间才动作</strong>(或者断电后延时返回),用于按时间顺序控制的场合。</p><h3 id="_1-两种延时方式" tabindex="-1">1. 两种延时方式 <a class="header-anchor" href="#_1-两种延时方式" aria-label="Permalink to &quot;1. 两种延时方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>动作特点</th></tr></thead><tbody><tr><td><strong>通电延时</strong></td><td>线圈通电,延时开始;到时间后触头动作</td></tr><tr><td><strong>断电延时</strong></td><td>线圈通电立即动作;断电后延时,时间到才返回</td></tr></tbody></table><h3 id="_2-常见类型" tabindex="-1">2. 常见类型 <a class="header-anchor" href="#_2-常见类型" aria-label="Permalink to &quot;2. 常见类型&quot;">​</a></h3><ul><li>空气阻尼式(气囊式):结构简单,延时范围有限;</li><li>电磁式、电动式;</li><li><strong>电子式</strong>:延时准确、范围大,现代最常用。</li></ul><h3 id="_3-典型应用" tabindex="-1">3. 典型应用 <a class="header-anchor" href="#_3-典型应用" aria-label="Permalink to &quot;3. 典型应用&quot;">​</a></h3><ul><li><strong>电动机星三角(Y-△)降压启动</strong>:启动时先 Y 形接法,延时到时间后自动切换成 △ 形——时间继电器是切换&quot;指挥&quot;;</li><li><strong>顺序启动控制</strong>:几台设备按时间先后依次启动。</li></ul><blockquote><p>💡 星三角启动为什么要延时切换?因为电动机启动瞬间电流很大,先降压启动(星形)减小冲击,转速起来后再切全压(三角形)——这个切换动作就靠时间继电器控制(第 8.4 节详讲)。</p></blockquote><h2 id="三、考点提示" tabindex="-1">三、考点提示 <a class="header-anchor" href="#三、考点提示" aria-label="Permalink to &quot;三、考点提示&quot;">​</a></h2><ul><li>✅ 中间继电器 = 增加触点数量、扩大控制容量,只用于控制回路。</li><li>✅ 时间继电器 = 延时动作,分<strong>通电延时/断电延时</strong>。</li><li>✅ 时间继电器常用于星三角启动、顺序控制。</li><li>⚠️ 易混点:中间继电器(加触点)和时间继电器(加延时)名字像、作用不同。</li></ul><h2 id="四、本节小结" tabindex="-1">四、本节小结 <a class="header-anchor" href="#四、本节小结" aria-label="Permalink to &quot;四、本节小结&quot;">​</a></h2><ul><li>中间继电器负责&quot;扩路&quot;,时间继电器负责&quot;定时&quot;。</li><li>时间继电器是星三角启动、顺序控制的&quot;指挥员&quot;。</li><li>两者的触头容量都小,用于控制回路。</li></ul><h2 id="五、自测练习" tabindex="-1">五、自测练习 <a class="header-anchor" href="#五、自测练习" aria-label="Permalink to &quot;五、自测练习&quot;">​</a></h2><ol><li>(判断)中间继电器的作用是增加触点的数量和扩大控制容量。( )</li><li>(单选)时间继电器主要用于()控制。 A. 短路　B. 时间顺序　C. 漏电　D. 过载</li><li>(判断)通电延时时间继电器,线圈通电后需延时到设定时间才动作。( )</li><li>(单选)电动机星三角降压启动中,负责切换 Y/△ 接法的是()。 A. 熔断器　B. 时间继电器　C. 热继电器　D. 刀开关</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。扩触点、扩容量。</li><li><strong>B</strong>。时间继电器按时间顺序控制。</li><li><strong>√</strong>。通电延时:通电开始计时,到时间动作。</li><li><strong>B</strong>。时间继电器控制星三角切换时机。</li></ol></details>',24)])])}const c=a(r,[["render",n]]);export{g as __pageData,c as default};
